"""Assemble the banner: the sky, then each layer from back to front."""

from anims import CYCLE, Anims

W, H = 1200, 360
SERIF = '"Didot", "Bodoni 72", "Playfair Display", "Noto Serif TC", Georgia, serif'
SANS = '"Avenir Next", ui-rounded, "PingFang TC", "Noto Sans TC", -apple-system, "Segoe UI", sans-serif'

LAYERS = [
]


def render(p: dict) -> str:
    an = Anims()
    body = "".join(layer(p, an) for layer in LAYERS)
    keyframes = "\n      ".join(an.rules)
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}">
  <!-- Generated by scripts/princess; edit the code there, not here. -->
  <defs>
    <linearGradient id="sky" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="{p["sky0"]}"/><stop offset=".55" stop-color="{p["sky1"]}"/><stop offset="1" stop-color="{p["sky2"]}"/>
    </linearGradient>
    <clipPath id="card"><rect width="{W}" height="{H}" rx="20"/></clipPath>
    <style>
      .kicker {{ font: 600 13px {SANS}; fill: {p["soft"]}; letter-spacing: 4px; }}
      .mast {{ font: italic 400 140px {SERIF}; fill: {p["mast"]}; letter-spacing: -3px; }}
      .role {{ font: 600 16px {SANS}; fill: #ffffff; letter-spacing: 1px; }}
      .tagline {{ font: italic 400 17px {SERIF}; fill: {p["soft"]}; }}

      .a {{ animation-duration: {CYCLE:g}s; animation-iteration-count: infinite; animation-timing-function: ease-in-out; }}
      .fb {{ transform-box: fill-box; transform-origin: center; }}
      {keyframes}
    </style>
  </defs>

  <g clip-path="url(#card)">
    <rect width="{W}" height="{H}" fill="url(#sky)"/>
    {body}
  </g>
</svg>
'''
